string raw = "GET / HTTP/1.1\r\nHost: example.test\r\nConnection: close\r\n\r\n";
using var reader = new StringReader(raw);
_ = reader.ReadLine();
var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
string? line;
while (true)
{
    line = reader.ReadLine();
    if(line is null)throw new EndOfStreamException("Header chưa kết thúc");
    if(line.Length==0)break;
    int colon = line.IndexOf(':');
    if (colon <= 0) throw new FormatException("Header sai");
    values.Add(line[..colon], line[(colon + 1)..].Trim());
}
Console.WriteLine(values.ContainsKey("host"));
Console.WriteLine(values["Connection"]);

